async function referenceFor(book,anchor,entry){
 if(!entry||!isVisibleAt(entry,anchor))return undefined;
 const p=entry.prepared;if(p?.selectionVersion!==2)return {quote:'',text:entry.reply};
 const {plan,source}=await getPreparedPlan(book);
 if(current!==book||p.source!==plan.source||p.bookId!==book.id||source.text.slice(p.quoteStart,p.quoteEnd)!==p.quote||source.position(anchor)<p.allowedEnd)return undefined;
 return {quote:p.quote,text:entry.reply,start:p.quoteStart,end:p.quoteEnd,allowedEnd:p.allowedEnd,source:p.source};
}
