async function updateWakeLock(){const revision=++awakeRevision,active=!!readingPreferences?.values.keepAwake&&document.body.classList.contains('is-reading')&&!document.hidden;if(window.OnePageReading){window.OnePageReading.keepAwake(active);return}if(!active){if(wakeLock){await wakeLock.release();wakeLock=null}return}if(wakeLock)return;if(!navigator.wakeLock)throw Error('此设备不支持保持常亮');const lock=await navigator.wakeLock.request('screen');if(revision!==awakeRevision||!document.body.classList.contains('is-reading')||document.hidden){await lock.release();return}wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null})}
