// Geometry fallback remains valid when a reading tool overlays the hit-test point.
function textRangeNearTop(root,wrap){
 const y=wrap.getBoundingClientRect().top+10,walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walker.nextNode()){
  if(!node.length)continue;
  const range=document.createRange();range.selectNodeContents(node);
  const bounds=range.getBoundingClientRect();if(!bounds.height||bounds.bottom<y)continue;
  let low=0,high=node.length-1;
  while(low<high){const mid=Math.floor((low+high)/2);range.setStart(node,mid);range.setEnd(node,mid+1);if(range.getBoundingClientRect().bottom<y)low=mid+1;else high=mid;}
  range.setStart(node,low);range.setEnd(node,Math.min(node.length,low+1));
  if(range.getBoundingClientRect().height)return range;
 }
 return null;
}
function captureSettingsPosition(){if(!current||!readingReady||$('reading').classList.contains('hidden')){settingsAnchor=null;return}if(current.type==='ebook'){settingsAnchor={book:current,view:ebookView,cfi:ebookView?.lastLocation?.cfi};return}if(current.type!=='txt'){settingsAnchor=null;return}const root=$('txt'),wrap=$('readerWrap'),bounds=wrap.getBoundingClientRect(),rect=root.getBoundingClientRect(),x=Math.max(bounds.left+1,Math.min(bounds.right-2,rect.left+parseFloat(getComputedStyle(root).paddingLeft)+2)),caret=document.caretRangeFromPoint?.(x,bounds.top+10);const valid=caret&&root.contains(caret.startContainer)&&caret.startContainer.nodeType===Node.TEXT_NODE;const located=valid?caret:textRangeNearTop(root,wrap);if(!located)return;const range=located.cloneRange();range.setEnd(range.startContainer,Math.min(range.startContainer.length,range.startOffset+1));settingsAnchor={book:current,encoding:$('encoding').value,seen:currentAnchor(),range,top:range.getBoundingClientRect().top-bounds.top}}
function restoreTextPosition(){const snapshot=settingsAnchor;if(!snapshot?.range||snapshot.book!==current||snapshot.encoding!==$('encoding').value||!snapshot.range.startContainer.isConnected||$('reading').classList.contains('hidden'))return;const token=++textRestoreToken;restoringTextStyle=true;requestAnimationFrame(()=>{if(token!==textRestoreToken){return}try{if(snapshot.book!==current||!snapshot.range.startContainer.isConnected||$('reading').classList.contains('hidden')||!readingReady)return;const wrap=$('readerWrap'),difference=snapshot.range.getBoundingClientRect().top-wrap.getBoundingClientRect().top-snapshot.top;wrap.scrollTop+=difference;current.progress=wrap.scrollTop/Math.max(1,wrap.scrollHeight-wrap.clientHeight);updateProgress();annotations?.paint();clearTimeout(saveTimer);const book=current;saveTimer=setTimeout(()=>put(book).then(shelf).catch(console.error),250)}finally{requestAnimationFrame(()=>{if(token===textRestoreToken)restoringTextStyle=false})}})}
